/**
 * ATLAS — Domain Knowledge Import
 * Domains: AI Model Releases · SpaceX & Space · India
 * 200+ topics across entities, sources, claims, conflicts, knowledge docs
 *
 * Usage: node scripts/import-domains.mjs
 */

import dotenv from 'dotenv';
dotenv.config();

const PROJECT_ID = process.env.SANITY_PROJECT_ID;
const DATASET    = process.env.SANITY_DATASET || 'production';
const TOKEN      = process.env.SANITY_API_TOKEN;
const API_VER    = process.env.SANITY_API_VERSION || '2024-01-01';

if (!PROJECT_ID || !TOKEN) {
  console.error('ERROR: SANITY_PROJECT_ID and SANITY_API_TOKEN must be set in .env');
  process.exit(1);
}

const BASE_URL = `https://${PROJECT_ID}.api.sanity.io/v${API_VER}/data/mutate/${DATASET}`;

async function mutate(mutations) {
  const res = await fetch(BASE_URL, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${TOKEN}` },
    body: JSON.stringify({ mutations }),
  });
  const json = await res.json();
  if (!res.ok) throw new Error(`Sanity API error ${res.status}: ${JSON.stringify(json)}`);
  return json;
}

