// MAIN IMPORT
// ═══════════════════════════════════════════════════════════════════════════

async function importAll() {
  const allDocs = [
    ...AI_ENTITIES,   ...AI_SOURCES,   ...AI_CLAIMS,   ...AI_CONFLICTS,   ...AI_KNOWLEDGE_DOCS,
    ...SPACE_ENTITIES,...SPACE_SOURCES, ...SPACE_CLAIMS, ...SPACE_CONFLICTS, ...SPACE_KNOWLEDGE_DOCS,
    ...INDIA_ENTITIES,...INDIA_SOURCES, ...INDIA_CLAIMS, ...INDIA_CONFLICTS, ...INDIA_KNOWLEDGE_DOCS,
  ];

  const domains = [
    { name: 'AI Models',       count: AI_ENTITIES.length + AI_SOURCES.length + AI_CLAIMS.length + AI_CONFLICTS.length + AI_KNOWLEDGE_DOCS.length },
    { name: 'SpaceX & Space',  count: SPACE_ENTITIES.length + SPACE_SOURCES.length + SPACE_CLAIMS.length + SPACE_CONFLICTS.length + SPACE_KNOWLEDGE_DOCS.length },
    { name: 'India',           count: INDIA_ENTITIES.length + INDIA_SOURCES.length + INDIA_CLAIMS.length + INDIA_CONFLICTS.length + INDIA_KNOWLEDGE_DOCS.length },
  ];

  console.log('\n╔══════════════════════════════════════════════════╗');
  console.log('║   ATLAS Knowledge Base — Domain Import           ║');
  console.log('╚══════════════════════════════════════════════════╝');
  console.log(`\nProject: ${PROJECT_ID} / Dataset: ${DATASET}`);
  console.log(`Total documents: ${allDocs.length}\n`);
  domains.forEach(d => console.log(`  • ${d.name}: ${d.count} documents`));
  console.log('');

  const BATCH = 10;
  let total = 0;

  for (let i = 0; i < allDocs.length; i += BATCH) {
    const batch = allDocs.slice(i, i + BATCH);
    const mutations = batch.map(doc => ({ createOrReplace: doc }));
    try {
      await mutate(mutations);
      total += batch.length;
      const pct = Math.round((total / allDocs.length) * 100);
      process.stdout.write(`\r  Importing... ${total}/${allDocs.length} (${pct}%)`);
    } catch (err) {
      console.error(`\n  ✗ Batch failed at index ${i}:`, err.message);
      process.exit(1);
    }
  }

  console.log(`\n\n✓ Import complete — ${allDocs.length} documents added to Sanity`);
  console.log('\n── Sample questions to try ──────────────────────────────────');
  console.log('  Was Sam Altman fired from OpenAI?');
  console.log('  Did Starship successfully launch?');
  console.log('  Did Chandrayaan-3 land on the Moon?');
  console.log('  What happened to Byju\'s valuation?');
  console.log('  When did India surpass China in population?');
  console.log('  Was LLaMA 1 open source?');
  console.log('  Did the Gemini launch demo show real capabilities?');
  console.log('  When did India launch 5G?');
  console.log('\nRestart your ATLAS server to pick up new knowledge.\n');
}

importAll();
